@page "/courses"
@inject UniversityCourseCatalog.Services.CatalogService CatalogService
@inject NavigationManager Navigation
@rendermode InteractiveServer

<PageTitle>Browse Courses</PageTitle>

<h1>Browse Courses</h1>

<div class="row mb-3">
    <div class="col-md-6">
        <input type="text" class="form-control" placeholder="Search by title, code, or instructor..."
               @bind="SearchTerm" @bind:event="oninput" />
    </div>
    <div class="col-md-4">
        <select class="form-select" @bind="SelectedDepartmentId">
            <option value="0">All Departments</option>
            @foreach (var dept in CatalogService.GetDepartments())
            {
                <option value="@dept.Id">@dept.Code - @dept.Name</option>
            }
        </select>
    </div>
</div>

@{
    var results = CatalogService.SearchCourses(SearchTerm, SelectedDepartmentId);
}

<p class="text-muted">Showing @results.Count course(s)</p>

<table class="table table-striped table-hover">
    <thead>
        <tr>
            <th>Code</th>
            <th>Title</th>
            <th>Credits</th>
            <th>Instructor</th>
            <th>Schedule</th>
            <th></th>
        </tr>
    </thead>
    <tbody>
        @foreach (var course in results)
        {
            <tr>
                <td>@course.FullCode</td>
                <td>@course.Title</td>
                <td>@course.Credits</td>
                <td>@course.InstructorName</td>
                <td>@course.Schedule</td>
                <td><a href="/courses/@course.Id" class="btn btn-outline-primary btn-sm">Details</a></td>
            </tr>
        }
    </tbody>
</table>

@code {
    private string? SearchTerm { get; set; }
    private int SelectedDepartmentId { get; set; }

    protected override void OnInitialized()
    {
        var uri = new Uri(Navigation.Uri);
        var query = System.Web.HttpUtility.ParseQueryString(uri.Query);
        if (int.TryParse(query["departmentId"], out var deptId))
        {
            SelectedDepartmentId = deptId;
        }
    }
}

@page "/enroll"
@inject UniversityCourseCatalog.Services.CatalogService CatalogService
@inject NavigationManager Navigation

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>
<p>Submit your enrollment request below. You will receive confirmation via your university email.</p>

@if (Submitted)
{
    <div class="alert alert-success">
        <h4>Request Submitted!</h4>
        <p>Your enrollment request has been submitted successfully. You will be notified of your enrollment status.</p>
        <a href="/courses" class="btn btn-primary">Browse More Courses</a>
    </div>
}
else
{
    <div class="row">
        <div class="col-md-6">
            <form method="post" @formname="enrollment" @onsubmit="HandleSubmit">
                <AntiforgeryToken />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name</label>
                    <input type="text" class="form-control" id="studentName" name="StudentName"
                           @bind="Model.StudentName" required />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <input type="text" class="form-control" id="studentId" name="StudentId"
                           @bind="Model.StudentId" required placeholder="e.g., STU-12345" />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <select class="form-select" id="courseId" name="CourseId" @bind="Model.CourseId" required>
                        <option value="0" disabled>Select a course...</option>
                        @foreach (var course in CatalogService.GetCourses())
                        {
                            <option value="@course.Id">@course.FullCode - @course.Title</option>
                        }
                    </select>
                </div>

                <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
                <a href="/courses" class="btn btn-secondary ms-2">Cancel</a>
            </form>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm]
    private UniversityCourseCatalog.Models.EnrollmentRequest Model { get; set; } = new();

    private bool Submitted { get; set; }

    protected override void OnInitialized()
    {
        var uri = new Uri(Navigation.Uri);
        var query = System.Web.HttpUtility.ParseQueryString(uri.Query);
        if (int.TryParse(query["courseId"], out var courseId) && Model.CourseId == 0)
        {
            Model.CourseId = courseId;
        }
    }

    private void HandleSubmit()
    {
        if (!string.IsNullOrWhiteSpace(Model.StudentName) &&
            !string.IsNullOrWhiteSpace(Model.StudentId) &&
            Model.CourseId > 0)
        {
            CatalogService.SubmitEnrollmentRequest(Model);
            Submitted = true;
        }
    }
}

